def exp(id,de,en,ode,oen):return dict(id=id,essentialUnderstandingDe=de,essentialUnderstandingEn=en,observablePerformanceDe=ode,observablePerformanceEn=oen)
def case(id,d,e,p,q,f,g):return dict(id=id,taskDemandDe=d,taskDemandEn=e,expectedPerformanceDe=p,expectedPerformanceEn=q,understandingFocusDe=f,understandingFocusEn=g)
asc=[exp('ascorbic-structure-and-suitable-method','Die reduzierende Molekülstruktur der Ascorbinsäure kann eine geeignete redoxstöchiometrische Bestimmung begründen. Bei einer geeigneten Iodbestimmung reagieren Ascorbinsäure und I₂ im Stoffmengenverhältnis1:1. Das macht einen Iodverbrauch in einer unbekannten Matrix nicht automatisch ascorbinspezifisch.','The reducing molecular structure of ascorbic acid can justify an appropriate redox-stoichiometric assay. In a suitable iodine assay, ascorbic acid and I₂ react in a1:1 molar ratio. This does not automatically make iodine consumption in an unknown matrix specific to ascorbic acid.','Aus der bereitgestellten Molekülstruktur und den Matrixbedingungen eine geeignete quantitative Ascorbinbestimmung auswählen und die relevante Kalibrierung oder Reaktionsstöchiometrie begründen.','Select an appropriate quantitative ascorbic assay from the supplied molecular structure and matrix conditions, and justify the relevant calibration or reaction stoichiometry.'),exp('actual-controlled-ascorbic-planning-and-execution','Das Ziel verlangt eigene Planung UND tatsächliche Durchführung mit passenden Blind-/Referenz- beziehungsweise Matrixkontrollen, bekannter Probenvorbereitung und Rohwerten. Eine Rechnung an bereitgestellten Beispielwerten oder ein simulierter Versuch belegt keine praktische Durchführung.','The goal requires the learner’s own planning AND actual execution with appropriate blank/reference or matrix controls, known sample preparation and raw measurements. Calculation using supplied example data or a simulated experiment does not demonstrate practical execution.','Einen geeigneten autorisierten Schulversuch planen und tatsächlich durchführen; eigene Vorbereitung, Kontrollen und Messwerte nachvollziehbar protokollieren.','Plan and actually perform an appropriate authorised school experiment; record the learner’s own preparation, controls and readings traceably.'),exp('ascorbic-content-dilution-and-interference','Ein tragfähiger Gehalt braucht korrekte Blindwertkorrektur, Stöchiometrie oder gültige Kalibrierung, Einheiten und Verdünnung. Oxidationsverluste und weitere reduzierende Matrixbestandteile können die Bestimmung verfälschen; zusätzliche Messungen oder eine geeignetere Methode können nötig sein.','A supported content requires correct blank correction, stoichiometry or valid calibration, units and dilution. Oxidative losses and other reducing matrix components can distort the assay; additional measurements or a more appropriate method may be needed.','Den Ascorbingehalt mit vollständigem Probenbezug bestimmen und bei einer frischen veränderten Matrix die Kontrolle tatsächlich prüfen, das Verfahren begründet anpassen und Grenzen des Ergebnisses benennen.','Determine ascorbic content with a complete sample basis, and for a fresh changed matrix actually examine controls, justify method adaptation and state the limits of the result.')]
asccases=[case('fresh-ascorbic-school-assay-own-records','Plane und führe eine geeignete quantitative Ascorbinsäurebestimmung an einer frischen geeigneten Schulprobe tatsächlich durch. Nutze die bereitgestellte Ascorbinstruktur zur Methodenwahl; dokumentiere eigene Probenvorbereitung, passenden Blindwert, Referenzkontrolle und Rohwerte. Zusätzliche Rechenkontrolle, nicht Durchführungsevidenz: I₂0,0045mol/L; Verbrauch10,60mL minus Blindwert0,60mL für20,00mL einer fünffach verdünnten Probe; M(Ascorbinsäure)=176,12g/mol; Stoffmengenverhältnis1:1.','Plan and actually perform an appropriate quantitative ascorbic-acid assay on a fresh suitable school sample. Use the supplied ascorbic structure to select the method; document the learner’s own preparation, appropriate blank, reference control and raw readings. Additional calculation check, not execution evidence: I₂0.0045mol/L; consumption10.60mL minus blank0.60mL for20.00mL of a fivefold-diluted sample; M(ascorbic acid)=176.12g/mol;1:1 molar ratio.','Eigene Planung und tatsächliche Durchführung sind belegt und von den Zusatzdaten getrennt. Kontrollrechnung: korrigierter Verbrauch10,00mL, n=0,000045mol, m=7,9254mg in20,00mL Messlösung;396,27mg/L Messlösung und1981,35mg/L Original. Kontrollen begründen die Gültigkeit für diese Matrix; nicht bloß allen Iodverbrauch ohne Störstoffprüfung Ascorbinsäure zuordnen.','The learner’s own planning and actual execution are evidenced separately from the extra data. Check: corrected consumption10.00mL, n=0.000045mol, m=7.9254mg in20.00mL measured solution;396.27mg/L measured solution and1981.35mg/L original. Controls establish validity for this matrix; do not simply attribute all iodine consumption to ascorbic acid without interference checks.','Strukturbegründete tatsächlich kontrollierte Bestimmung und vollständiger Probenbezug.','Structure-based actual controlled assay and complete sample basis.'),case('fresh-ascorbic-matrix-interference-and-new-measurement','Untersuche eine andere frische geeignete Probe mit veränderter Verdünnung. Ein bereitgestellter Matrixzusatz enthält zusätzlich einen reduzierenden Stoff. Plane UND führe Kontroll- und Bestimmungsschritte tatsächlich durch, um zu prüfen, ob ein erhöhter Iodverbrauch der Ascorbinsäure zugeordnet werden darf oder eine geeignetere Methode nötig ist. Rechenkontrolle nur unter nachgewiesen geeigneten Bedingungen: I₂0,0040mol/L;7,80mL minus0,30mL Blindwert in10,00mL einer dreifach verdünnten Probe.','Investigate a different fresh suitable sample with changed dilution. A supplied matrix addition includes another reducing substance. Plan AND actually perform control and assay steps to examine whether increased iodine consumption can be assigned to ascorbic acid or a more appropriate method is needed. Calculation check only under demonstrated suitable conditions: I₂0.0040mol/L;7.80mL minus0.30mL blank in10.00mL of a threefold-diluted sample.','Eigene frische Mess-/Kontrollprotokolle zeigen die Überprüfung. Mehrverbrauch durch weitere Reduktionsmittel wird nicht automatisch als Ascorbin gezählt; ein einfacher Lösemittelblindwert beseitigt nicht jede Matrixstörung. Geeignete zusätzliche Kontrollen beziehungsweise ein geeignetes spezifischeres Verfahren und neue Messungen sind erforderlich. Nur bei belegter Eignung gilt die Kontrollrechnung n=0,000030mol, m=5,2836mg,528,36mg/L Messlösung und1585,08mg/L Original. Andernfalls kein scheinpräziser Ascorbingehalt.','The learner’s fresh measurement/control records show the examination. Consumption by other reducing agents is not automatically counted as ascorbic acid; a simple solvent blank does not remove every matrix interference. Appropriate additional controls or a suitable more-selective procedure and new measurements are required. Only when suitability is evidenced does the check yield n=0.000030mol, m=5.2836mg,528.36mg/L measured solution and1585.08mg/L original. Otherwise do not report a falsely precise ascorbic content.','Eigenständiger frischer Experimentaltransfer, Matrixselektivität und ehrliche Verfahrensgrenzen.','Independent fresh experimental transfer, matrix selectivity and honest method limits.')]
est=[exp('specified-paraben-structure-and-method','Die bereitgestellte Struktur eines vorgegebenen p-Hydroxybenzoesäureesters begründet eine geeignete quantitative Mess- und Trennmethode. Ein geeignetes kalibriertes chromatographisches Verfahren ist ein Beispiel, nicht die einzige erlaubte Methode oder eine überall verfügbare Schulausstattung.','The supplied structure of a specified p-hydroxybenzoic acid ester justifies a suitable quantitative measurement and separation method. Appropriate calibrated chromatography is one example, not the only permitted method or equipment available in every school.','Für den tatsächlich vorgegebenen einzelnen Paraben-Ester eine geeignete Methode anhand von Struktur, Matrix und verfügbaren Verfahrensdaten auswählen und begründen.','Select and justify an appropriate method for the one actually specified paraben ester using structure, matrix and available method data.'),exp('actual-controlled-paraben-planning-and-execution','Die quantitative Parabenbestimmung verlangt eigene Planung UND tatsächliche Durchführung mit passenden Blind-/Matrixkontrollen, Referenzstandards und nachvollziehbarer Probenvorbereitung. Ein fremdes Chromatogramm oder eine simulierte Messung allein belegt keine eigene Durchführung.','Quantitative paraben determination requires the learner’s own planning AND actual execution with appropriate blank/matrix controls, reference standards and traceable preparation. Another person’s chromatogram or a simulated measurement alone does not demonstrate the learner’s execution.','Eine geeignete autorisierte Bestimmung für den vorgegebenen Ester tatsächlich planen und durchführen; eigene Kontrollen, Standards, Probenvorbereitung und Messwerte dokumentieren.','Actually plan and carry out a suitable authorised assay for the specified ester; document the learner’s own controls, standards, sample preparation and readings.'),exp('paraben-calibration-range-dilution-selectivity','Chromatographische Retentionszeit identifiziert Peaklagen und ist keine Konzentration. Ein geeigneter kalibrierter Signalbezug liefert Konzentration nur im validierten Arbeitsbereich; Verdünnung, unterschiedliche Analytenantwort und koeluierende Matrixbestandteile müssen berücksichtigt werden.','Chromatographic retention time locates peaks and is not concentration. Appropriate calibrated signal response gives concentration only within the validated working range; dilution, different analyte response and coeluting matrix components must be considered.','Kalibrierung oder passende Stöchiometrie gültig anwenden, den Gehalt mit Einheiten und Verdünnung bestimmen und bei frischer Range-/Selektivitätsstörung wirklich neu messen statt extrapolieren oder Peakzeit als Gehalt auszugeben.','Apply valid calibration or suitable stoichiometry, determine content with units and dilution, and for fresh range/selectivity interference actually remeasure rather than extrapolate or present peak time as content.')]
estcases=[case('fresh-specified-methylparaben-own-calibrated-assay','Plane und führe eine geeignete quantitative Bestimmung von vorgegebenem Methylparaben in einer geeigneten Schulprobe tatsächlich durch. In diesem konkreten Material steht ein freigegebenes HPLC-Verfahren zur Verfügung; begründe es aus Struktur und Matrix, nutze Blankprobe und analytspezifische Standards und lege eigene Vorbereitung, Kontroll- und Rohmessprotokolle vor. Zusätzliche Rechenkontrolle: Standards c=0,5;2,0;5,0mg/L liefern A=65;200;470. Gültiger Bereich0,5–5,0mg/L, Probenfläche A=290, Verdünnungsfaktor8.','Plan and actually perform an appropriate quantitative determination of specified methylparaben in a suitable school sample. This particular material provides an authorised HPLC procedure; justify it from structure and matrix, use a blank and analyte-specific standards, and submit the learner’s own preparation, control and raw-measurement records. Additional calculation check: standards c=0.5;2.0;5.0mg/L give A=65;200;470. Valid range0.5–5.0mg/L, sample area A=290, dilution factor8.','Die eigenen Durchführungsschritte und Kontrollen sind von den Zusatzdaten getrennt belegt. Kontrollgerade A=90c+20; c=3,0mg/L Messlösung und24,0mg/L Original, innerhalb des Bereichs. Retentionszeit ist nicht Konzentration; passende Standards und Matrix-/Trennkontrollen müssen die Zuordnung des Signals tragen. Kein Anspruch, HPLC sei überall verfügbar oder für alle Parabene zwingend.','The learner’s own execution and controls are evidenced separately from the extra data. Check line A=90c+20; c=3.0mg/L measured solution and24.0mg/L original, within range. Retention time is not concentration; appropriate standards and matrix/separation controls must support assignment of the signal. Do not claim HPLC is universally available or mandatory for every paraben.','Tatsächliche analytspezifische Bestimmung, getrennte Zeit-/Konzentrationsachsen und gültige Kalibrierung.','Actual analyte-specific assay, distinct time/concentration axes and valid calibration.'),case('fresh-specified-ethylparaben-range-and-matrix-remeasurement','Plane und führe eine Bestimmung an einer frischen geeigneten Probe des nun vorgegebenen Ethylparabens durch; begründe geeignete Methode und Standards erneut aus seiner bereitgestellten Struktur. Eine Peaküberlagerung durch Matrix ist zunächst möglich. Die neue gültige Kalibrierung A=75c+10 gilt nur0,5–4,0mg/L. Nach anfänglicher Probenverdünnung6 liefert die Probe A=460. Plane UND führe geeignete Selektivitätskontrollen und zusätzliche Verdünnung mit neuer Messung aus; eine weitere dreifache Verdünnung liefert bei geeigneter Trennung A=160.','Plan and carry out an assay on a fresh suitable sample of now-specified ethylparaben; justify suitable method and standards again using its supplied structure. Matrix peak overlap is initially possible. New valid calibration A=75c+10 applies only to0.5–4.0mg/L. After initial sample dilution6 the sample gives A=460. Plan AND actually perform appropriate selectivity controls and additional dilution with new measurement; a further threefold dilution gives A=160 when separation is suitable.','Eigene frische Kontroll-/Messprotokolle belegen Durchführung und geprüfte Trennung; weder identische Retentionszeit noch allein ein Standard beweisen Abwesenheit von Koelution. A=460 ergäbe6,0mg/L außerhalb des Bereichs und darf nicht als gültiger Gehalt extrapoliert werden. Neue tatsächlich geeignet getrennte Messung A=160 liefert2,0mg/L; Gesamtverdünnung18 ergibt36,0mg/L Original. Ohne belegte Selektivität bleibt die präzise analytspezifische Gehaltsangabe offen. Keine ungeprüfte Übernahme der Methylparaben-Kalibrierung.','The learner’s fresh control/measurement records demonstrate execution and checked separation; neither matching retention time nor a standard alone proves absence of coelution. A=460 would give6.0mg/L outside range and cannot be extrapolated as a valid content. The new actually suitably separated measurement A=160 gives2.0mg/L; total dilution18 gives36.0mg/L original. Without evidenced selectivity the precise analyte-specific content remains open. Do not reuse the methylparaben calibration unchecked.','Frischer eigenständiger analytspezifischer Experimentaltransfer mit Bereichs- und Matrixgrenzen.','Fresh independent analyte-specific experimental transfer with range and matrix limitations.')]
def make(gid,expectations,cases,variationDe,variationEn):
 return {'goalId':gid,'reason':'Informed new atomic-split AUTHOR candidate, not independent science approval. Actual learner planning AND execution are future evidence requirements, not AI-observed laboratory work. Fresh bilingual case payloads; E1/G1 ai_candidate needs_human_review. Independent D/P/A/M/V and source/course review pending.','evidenceLevel':'E1','maximumClaimScope':'G1','dissent':[],'profile':{'archetype':'procedure','expectations':expectations,'coverageExpectations':{'requiredExpectationIds':[x['id']for x in expectations],'alternativeExpectationGroups':[],'minimumIndependentDemonstrations':2,'freshVariationRequired':True,'independentTransferRequired':True},'variationAxes':[{'id':'fresh-analyte-specific-controlled-assay','textDe':variationDe,'textEn':variationEn}],'applicationCaseBriefs':cases}}
original=json.loads((OLD/'positive-evidence.candidates.json').read_text());keep=[copy.deepcopy(x)for x in original['goals'] if x['goalId']!='d3cd250f-5221-589d-aa1c-44a4692d1acb'];assert len(keep)==6
children=[make(ASC,asc,asccases,'Frische geeignete Ascorbinprobe, veränderte Verdünnung/Blindwert, Referenzkontrolle, weitere Reduktionsmittel, tatsächliche eigene Planung/Durchführung.','Fresh suitable ascorbic sample, changed dilution/blank, reference control, other reducing agents, the learner’s actual planning/execution.'),make(EST,est,estcases,'Jeweils ein vorgegebener Ester und frische Matrix; geeignete neue analytspezifische Standards, veränderte Verdünnung/Kalibrierung, Arbeitsbereich und Koelution; tatsächliche Planung/Durchführung.','One specified ester at a time and fresh matrix; suitable new analyte-specific standards, changed dilution/calibration, working range and coelution; actual planning/execution.')]
header={k:copy.deepcopy(v)for k,v in original.items()if k!='goals'};header.update(reviewId='chemie-q1-atomic-split-p-author-20261005-v1',reviewedAt=datetime.datetime.now(datetime.timezone.utc).isoformat(),reviewer='Codex informed atomic-split AUTHOR; independent review pending')
for fn,rows in [('positive-evidence.candidates.json',keep+children),('positive-evidence.two-new-children.candidates.json',children)]:
 (O/fn).write_text(json.dumps(dict(header,goals=rows),ensure_ascii=False,indent=2)+'\n')
(O/'six-prior-inner-positive-profiles.exact-preservation.actual.json').write_text(json.dumps({'sixGoalIds':[x['goalId']for x in keep],'allSixInnerProfilesByteRepresentationExact':all(json.dumps(x['profile'],sort_keys=True,ensure_ascii=False)==json.dumps(next(y for y in original['goals']if y['goalId']==x['goalId'])['profile'],sort_keys=True,ensure_ascii=False)for x in keep),'newChildrenRequireIndependentReview':True,'oldD3CompoundProfileNotAdopted':True,'actualLabPerformanceClaimed':False,'activeWrites':0},ensure_ascii=False,indent=2)+'\n')
print('8 author profiles, 6 exact prior inner payloads, 2 new child profiles / 4 fresh DEEN cases; no independent approval')
